/**
 * @opencode-compat/adapter — universal host adapter.
 * Autodetect HostProfile; dispatch to native SDK. No per-host publishable packages.
 * See docs/ocp/0.1.md and docs/plans/.
 */
export const PKG = "@opencode-compat/adapter";
export const VERSION = "0.4.4";
export { detect, } from "@opencode-compat/profile";
export { createPromiseV2Host, define as definePromisePlugin, runPromisePlugin, } from "@opencode-compat/host-promise-v2";
export { adaptLanguageModel, adaptLanguageModelForProfile, adoptStreamPart, canonicalToolKey, defaultBashDescription, normalizeToolInputForSchema, policyForHostId, policyFromProfile, wrapProviderModule, wrapProviderModuleForProfile, wrapProviderSdk, wrapProviderSdkForProfile, } from "./language-model";
export { buildVocabulary, compareCanonicalKeys, allocateProvisionalHostIds, diffTodos, fanoutId, originalCallId, reconstructHostTodos, translateCall, translateCatalog, translatePrompt, translateResultOutput, } from "./vocabulary";
export { RUNTIME_FILENAME, SHIM_MARKER, SHIM_META_FILENAME, providerShimRuntimeSource, renderProviderShimSource, renderShimMeta, stripProviderShimSource, } from "./shim-source";
import { createPromiseV2Host, } from "@opencode-compat/host-promise-v2";
import { detect, formatProfileSummary, privacyGuideHint, } from "@opencode-compat/profile";
import { adaptLanguageModelForProfile, wrapProviderSdkForProfile, } from "./language-model";
import { installPathBridge } from "./runtime-host";
import { installSkillsBridge } from "./skills-bridge";
import { providerUsageIntegrationForHost } from "./provider-usage";
export { providerUsageIntegrationForHost, usageEventPlugin } from "./provider-usage";
/** Resolve the active host profile (throws if OCP load is not supported). */
export function requireHost(options) {
    const result = detect(options);
    if (!result.supported) {
        throw new Error(result.message ?? `OCP: host ${result.id} is not supported`);
    }
    return result.profile;
}
/**
 * Wire OCP-layer Promise v2 host kit for the active profile.
 * Call `host.register(plugin)` then `host.resolveProvider(input)` at
 * provider-resolve time (sidecar / operator helper — no host source edits).
 *
 * Returned `language` / `sdk` are host-adapted (MiMo stream preamble and bash
 * description when required; MiMo and Kilo clear a finished todo snapshot).
 *
 * Also installs the path bridge so unchanged OpenCode plugins resolve
 * project/global config dirs for the detected host (CreatePlan, skills, …).
 */
export function wirePromiseV2(options) {
    const profile = requireHost(options);
    if (!profile.capabilities.promiseV2) {
        throw new Error(`${PKG}: Promise v2 not available on host "${profile.id}". ` +
            "See docs/ocp/0.1.md §7.");
    }
    installPathBridge(profile.id, options?.env);
    installSkillsBridge(profile.id);
    const host = createPromiseV2Host(options?.pluginOptions ?? {});
    return {
        ctx: host.ctx,
        register: (plugin) => host.register(plugin),
        remove: (id) => host.remove(id),
        plugins: () => host.plugins(),
        async resolveProvider(input) {
            const result = await host.resolveProvider(input);
            const usage = providerUsageIntegrationForHost(profile.id, options?.env, input.package);
            return {
                ...result,
                language: result.language != null
                    ? adaptLanguageModelForProfile(result.language, profile, usage)
                    : result.language,
                sdk: result.sdk != null
                    ? wrapProviderSdkForProfile(result.sdk, profile, usage)
                    : result.sdk,
            };
        },
    };
}
/** Native package names for the detected (or given) profile. */
export function nativePackages(profile) {
    return {
        plugin: profile.nativePlugin,
        sdk: profile.nativeSdk,
    };
}
/**
 * Whether a portable classic hook should be treated as a no-op gap
 * (accept on facade, warn via doctor) on this host.
 */
export function isNoopHookGap(profile, hook) {
    return profile.hooks.missing.includes(hook);
}
/** Warnings for hooks present on a plugin that the host cannot invoke. */
export function missingHookWarnings(profile, hooks) {
    const warnings = [];
    for (const name of profile.hooks.missing) {
        if (hooks[name] != null) {
            warnings.push(`OCP: host "${profile.id}" missing hook "${name}" — accepted as no-op (compat gap)`);
        }
    }
    return warnings;
}
/**
 * Normalize classic hooks for the active host: keep portable hooks, surface
 * doctor warnings for MiMo gaps, strip non-portable extension keys from the
 * portable path (extensions stay host-only).
 */
export function normalizeHooks(hooks, profile, options) {
    for (const message of missingHookWarnings(profile, hooks)) {
        options?.onWarn?.(message);
    }
    return hooks;
}
/** Build a specifier for a native plugin subpath (e.g. `@mimo-ai/plugin/tui`). */
export function nativePluginSpecifier(subpath, options) {
    const profile = requireHost(options);
    const base = profile.nativePlugin;
    if (!subpath || subpath === "." || subpath === "")
        return base;
    const cleaned = subpath.replace(/^\.\//, "").replace(/^\//, "");
    return `${base}/${cleaned}`;
}
/** Build a specifier for a native SDK subpath. */
export function nativeSdkSpecifier(subpath, options) {
    const profile = requireHost(options);
    const base = profile.nativeSdk;
    if (!subpath || subpath === "." || subpath === "")
        return base;
    const cleaned = subpath.replace(/^\.\//, "").replace(/^\//, "");
    return `${base}/${cleaned}`;
}
async function dynamicImport(specifier, importer) {
    if (importer)
        return importer(specifier);
    try {
        const mod = await import(specifier);
        return mod;
    }
    catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        throw new Error(`${PKG}: failed to import native module ${JSON.stringify(specifier)}: ${message}`);
    }
}
/** Dynamically import the host’s native plugin package (optional subpath). */
export async function importNativePlugin(subpath, options) {
    const specifier = nativePluginSpecifier(subpath, options);
    return dynamicImport(specifier, options?.importer);
}
/** Dynamically import the host’s native SDK package (optional subpath). */
export async function importNativeSdk(subpath, options) {
    const specifier = nativeSdkSpecifier(subpath, options);
    return dynamicImport(specifier, options?.importer);
}
/**
 * Wrap a classic plugin so returned hooks are normalized for the detected host.
 * The OCP layer / host kit may call this when loading `@opencode-ai/plugin` plugins via the bridge.
 */
export function wrapClassicPlugin(plugin, options) {
    const profile = requireHost(options);
    return async (input, pluginOptions) => {
        const hooks = await plugin(input, pluginOptions);
        return normalizeHooks(hooks, profile, { onWarn: options?.onWarn });
    };
}
/** Adapter-facing doctor report built on profile detect(). */
export function doctorReport(options) {
    const result = detect(options);
    const privacy = privacyGuideHint(result.id);
    const summary = [
        formatProfileSummary(result.profile),
        `source: ${result.source}`,
        `supported: ${result.supported}`,
        result.message ? `message: ${result.message}` : undefined,
        privacy,
    ]
        .filter(Boolean)
        .join("\n");
    return {
        ok: result.supported,
        result,
        summary,
    };
}
